void Solver::rephase() {
    // Reset the rephase counter.
    rephases = 0;

    // Make the next rephase a bit harder to trigger.
    // Reduce the threshold slightly (instead of the aggressive 0.9 factor).
    threshold = static_cast<int>(threshold * 0.95);

    // Grow the rephase limit adaptively so that rephases become less frequent
    // as the search progresses, but still allow occasional adjustments.
    rephase_limit = static_cast<int>(rephase_limit * 1.2) + 1024;

    // Choose a new saved polarity strategy.
    // 40 % – reuse the best phase seen so far,
    // 30 % – use the opposite of the best phase,
    // 30 % – pick a completely random polarity for each variable.
    int r = rand() % 100;
    if (r < 40) {
        // Use the best local assignment found so far.
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 70) {
        // Use the opposite polarity of the best local assignment.
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        // Random polarity for each variable.
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}
